import torch
import torch.nn as nn

from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

# ---------------------------------------------------------------------------
# Hand written PTX GEMM kernel.
#
# Computes C = A @ B for
#   A : (M, K)  row-major   (float32)
#   B : (K, N)  row-major   (float32)
#   C : (M, N)  row-major   (float32)
#
# CTA tile   : 64 (M) x 64 (N) x 32 (K)
# Block dim  : 256 threads, organised as a 16x16 grid of "compute" threads.
# Per thread : a 4x4 register-blocked sub-tile of C (16*4 == 64 in each dim).
#
# Optimization note:
# The previous version used a 128x128 CTA tile with an 8x8 per-thread
# register tile (64 accumulators per thread).  Profiling showed this
# resulted in ~126 registers/thread and theoretical occupancy capped at
# 33.3% (register bound), despite the workload being memory-throughput
# bound (~97% mem throughput, only ~17% compute throughput).  Shrinking
# the CTA tile to 64x64 with a 4x4 per-thread register tile (16
# accumulators per thread) sharply reduces register pressure and shared
# memory footprint (32KB -> 16KB per CTA), allowing many more concurrent
# CTAs/warps resident per SM to better hide global memory latency for
# this memory-bound, tall/skinny (K=32) GEMM.
#
# For the target workload (M = N = 32768, K = 32) M and N are multiples of
# 64 and K is a multiple of 32, matching the assumptions of this kernel.
# ---------------------------------------------------------------------------

PTX_SOURCE = r"""
.version 8.7
.target sm_89
.address_size 64

.visible .entry gemm_tallskinny(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 Mparam,
    .param .u32 Nparam,
    .param .u32 Kparam
)
{
    .reg .pred %p<8>;
    .reg .b32  %r<40>;
    .reg .b32  %t<40>;
    .reg .b64  %rd<10>;
    .reg .b64  %td<10>;
    .reg .f32  %f<40>;
    .reg .f32  %acc<16>;

    .shared .align 16 .b8 smemA[8192];   // 64 x 32 floats
    .shared .align 16 .b8 smemB[8192];   // 32 x 64 floats

    // ---- parameters ----------------------------------------------------
    ld.param.u64 %rd0, [A_ptr];
    ld.param.u64 %rd1, [B_ptr];
    ld.param.u64 %rd2, [C_ptr];
    ld.param.u32 %r0,  [Mparam];
    ld.param.u32 %r1,  [Nparam];
    ld.param.u32 %r2,  [Kparam];

    cvta.to.global.u64 %rd0, %rd0;
    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;

    // ---- block / thread indices -----------------------------------------
    mov.u32 %r3, %ctaid.x;      // bx : M tile index
    mov.u32 %r4, %ctaid.y;      // by : N tile index
    mov.u32 %r5, %tid.x;        // tid (0..255)

    shr.u32 %r6, %r5, 4;        // ty = tid >> 4   (0..15)
    and.b32 %r7, %r5, 15;       // tx = tid & 15   (0..15)

    and.b32 %r8,  %r5, 31;      // k0  : local K coord used while loading A
    shr.u32 %r9,  %r5, 5;       // m0  : local M coord base while loading A

    and.b32 %r10, %r5, 63;      // n0  : local N coord used while loading B
    shr.u32 %r11, %r5, 6;       // kb0 : local K coord base while loading B

    shr.u32 %r12, %r2, 5;       // ntiles = K / 32

    shl.b32 %r13, %r3, 6;       // rowA_base = bx * 64
    shl.b32 %r14, %r4, 6;       // colB_base = by * 64

    // ---- per-thread shared-mem byte offsets used during the compute phase
    shl.b32 %t0, %r6, 9;        // ty * 512
    shl.b32 %t1, %r7, 4;        // tx * 16

    add.s32 %r15, %t0, 0;       // rA0 .. rA3 : (ty*4+i)*128
    add.s32 %r16, %t0, 128;
    add.s32 %r17, %t0, 256;
    add.s32 %r18, %t0, 384;

    add.s32 %r19, %t1, 0;       // cB0 .. cB3 : (tx*4+j)*4
    add.s32 %r20, %t1, 4;
    add.s32 %r21, %t1, 8;
    add.s32 %r22, %t1, 12;

    mov.u32 %r23, smemA;
    mov.u32 %r24, smemB;

    // ---- zero accumulators ----------------------------------------------
    mov.f32 %f0, 0f00000000;
    mov.f32 %acc0,  %f0;  mov.f32 %acc1,  %f0;  mov.f32 %acc2,  %f0;  mov.f32 %acc3,  %f0;
    mov.f32 %acc4,  %f0;  mov.f32 %acc5,  %f0;  mov.f32 %acc6,  %f0;  mov.f32 %acc7,  %f0;
    mov.f32 %acc8,  %f0;  mov.f32 %acc9,  %f0;  mov.f32 %acc10, %f0;  mov.f32 %acc11, %f0;
    mov.f32 %acc12, %f0;  mov.f32 %acc13, %f0;  mov.f32 %acc14, %f0;  mov.f32 %acc15, %f0;

    mov.u32 %r25, 0;            // kt = 0

LOOP_KT:
    setp.ge.s32 %p0, %r25, %r12;
    @%p0 bra END_KT;

    mul.lo.s32 %t2, %r25, 32;   // koff = kt * 32

    // ================= load A tile (64 x 32), 8 elems/thread, vectorized ==
    shr.u32 %t3, %r5, 2;        // rowA_local = tid >> 2  (0..63)
    and.b32 %t4, %r5, 3;        // colGroupA  = tid & 3   (0..3)
    shl.b32 %t5, %t4, 3;        // colBaseA   = colGroupA * 8
    add.s32 %t6, %r13, %t3;     // rowA = rowA_base + rowA_local
    add.s32 %t7, %t2, %t5;      // colA = koff + colBaseA
    mul.wide.s32 %td0, %t6, %r2;
    cvt.s64.s32 %td1, %t7;
    add.s64 %td0, %td0, %td1;
    shl.b64 %td0, %td0, 2;
    add.s64 %td0, %td0, %rd0;
    ld.global.v4.f32 {%f1, %f2, %f3, %f4}, [%td0];
    add.s64 %td1, %td0, 16;
    ld.global.v4.f32 {%f5, %f6, %f7, %f8}, [%td1];
    shl.b32 %t8, %t3, 7;        // rowA_local * 128
    shl.b32 %t9, %t5, 2;        // colBaseA * 4
    add.s32 %t8, %t8, %t9;
    add.s32 %t8, %t8, %r23;
    st.shared.v4.f32 [%t8], {%f1, %f2, %f3, %f4};
    add.s32 %t9, %t8, 16;
    st.shared.v4.f32 [%t9], {%f5, %f6, %f7, %f8};
    // ================= load B tile (32 x 64), 8 elems/thread, vectorized ==
    shr.u32 %t10, %r5, 3;       // rowB_local = tid >> 3  (0..31)
    and.b32 %t11, %r5, 7;       // colGroupB  = tid & 7   (0..7)
    shl.b32 %t12, %t11, 3;      // colBaseB   = colGroupB * 8
    add.s32 %t3, %t2, %t10;     // rowB = koff + rowB_local
    add.s32 %t4, %r14, %t12;    // colB = colB_base + colBaseB
    mul.wide.s32 %td2, %t3, %r1;
    cvt.s64.s32 %td3, %t4;
    add.s64 %td2, %td2, %td3;
    shl.b64 %td2, %td2, 2;
    add.s64 %td2, %td2, %rd1;
    ld.global.v4.f32 {%f9, %f10, %f11, %f12}, [%td2];
    add.s64 %td3, %td2, 16;
    ld.global.v4.f32 {%f13, %f14, %f15, %f16}, [%td3];
    shl.b32 %t5, %t10, 8;       // rowB_local * 256
    shl.b32 %t6, %t12, 2;       // colBaseB * 4
    add.s32 %t5, %t5, %t6;
    add.s32 %t5, %t5, %r24;
