class ModelNew(nn.Module):
    """
    Performs C = A @ B using a hand written PTX tiled GEMM kernel
    (64x64 CTA tile, 32-wide K tile, 4x4 register blocking per thread).
    Targeted for the tall/skinny workload where K is small relative to
    M and N.
    """

    def __init__(self) -> None:
        super().__init__()
        self._module = None

    def _get_module(self) -> PtxModule:
        if self._module is None:
            self._module = _get_module()
        return self._module

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        assert A.is_cuda and B.is_cuda, "A and B must be CUDA tensors"
        A = A.contiguous().to(torch.float32)
        B = B.contiguous().to(torch.float32)

        M, K = A.shape
        K2, N = B.shape
        assert K == K2, "inner dimensions of A and B must match"
        assert M % 64 == 0, "M must be a multiple of 64"
        assert N % 64 == 0, "N must be a multiple of 64"
        assert K % 32 == 0, "K must be a multiple of 32"

        C = torch.empty((M, N), device=A.device, dtype=torch.float32)

        module = self._get_module()
        stream = torch.cuda.current_stream(A.device)

        grid = (M // 64, N // 64, 1)
        block = (256, 1, 1)

        module.launch(
            _ENTRY_NAME,
            grid,
            block,
            [
                u64(A.data_ptr()),
                u64(B.data_ptr()),
                u64(C.data_ptr()),
                i32(M),
                i32(N),
                i32(K),
            ],
            stream=stream,
        )

        return C

